const crypto = require('node:crypto')
const { readJsonBody, replyJson: reply, sameOrigin } = require('./panel-http')
const { createTiming } = require('./panel-timing')

function createPanelEditor ({ panelId, username, password, secureCookie, getConfig, getDevices, getTargets, apply, restoredSessions, onAuthenticatedRequest, onSessionReady }) {
  if (!username || !password) return null
  const prefix = `/control-panel-edit/panels/${panelId}`
  const cookieName = `cp_edit_${panelId.replace(/[^a-zA-Z0-9]/g, '_')}`
  const salt = crypto.randomBytes(32)
  const passwordHash = crypto.scryptSync(password, salt, 32)
  const sessions = new Map()
  if (restoredSessions instanceof Map) {
    for (const [token, session] of restoredSessions) {
      if (sessions.size >= 100) break
      if (typeof token === 'string' && typeof session?.csrf === 'string' &&
        Number.isFinite(session.expiry) && session.expiry > Date.now()) {
        sessions.set(token, { csrf: session.csrf, expiry: session.expiry })
      }
    }
  }
  const attempts = new Map()
  const ttl = 30 * 60 * 1000
  let closed = false

  function cookie (value, age, req) {
    return `${cookieName}=${value}; Path=${prefix}; HttpOnly; SameSite=Strict; Max-Age=${age}${secureCookie && req.socket.encrypted ? '; Secure' : ''}`
  }

  async function handler (req, res) {
    const path = new URL(req.url, 'http://localhost').pathname
    if (!path.startsWith(prefix + '/')) return false
    if (closed) { reply(res, 503, { error: 'Editor unavailable' }); return true }
    if (req.method === 'POST' && !sameOrigin(req)) {
      reply(res, 403, { error: 'Origin rejected' })
      return true
    }
    const now = Date.now()
    for (const [token, session] of sessions) if (session.expiry <= now) sessions.delete(token)
    for (const [ip, attempt] of attempts) if (attempt.until <= now) attempts.delete(ip)
    try {
      if (path === prefix + '/login' && req.method === 'POST') {
        const ip = String(req.socket.remoteAddress || 'unknown')
        const attempt = attempts.get(ip) || { count: 0, until: now + 60000 }
        if (attempt.count >= 10 || attempts.size > 1000) {
          reply(res, 429, { error: 'Too many attempts' })
          return true
        }
        attempt.count++
        attempts.set(ip, attempt)
        const body = await readJsonBody(req, 65536)
        const supplied = String(body.password || '')
        if (supplied.length > 256) { reply(res, 401, { error: 'Invalid credentials' }); return true }
        const test = await new Promise((resolve, reject) => crypto.scrypt(supplied, salt, 32,
          (error, key) => error ? reject(error) : resolve(key)))
        if (body.username !== username || !crypto.timingSafeEqual(test, passwordHash)) {
          reply(res, 401, { error: 'Invalid credentials' })
          return true
        }
        attempts.delete(ip)
        if (sessions.size >= 100) { reply(res, 503, { error: 'Session limit reached' }); return true }
        const token = crypto.randomBytes(32).toString('hex')
        const csrf = crypto.randomBytes(24).toString('hex')
        sessions.set(token, { csrf, expiry: now + ttl })
        reply(res, 200, { csrf }, { 'Set-Cookie': cookie(token, ttl / 1000, req) })
        onSessionReady?.()
        return true
      }
      const token = String(req.headers.cookie || '').split(';').map(part => part.trim())
        .find(part => part.startsWith(cookieName + '='))?.slice(cookieName.length + 1)
      const session = sessions.get(token)
      if (!session) { reply(res, 401, { error: 'Editor login required' }); return true }
      if (req.method === 'POST' && req.headers['x-panel-csrf'] !== session.csrf) {
        reply(res, 403, { error: 'CSRF rejected' })
        return true
      }
      if (onAuthenticatedRequest && await onAuthenticatedRequest(req, res,
        { token, expiry: session.expiry })) return true
      if (path === prefix + '/session' && req.method === 'GET') {
        reply(res, 200, { csrf: session.csrf })
        onSessionReady?.()
      } else if (path === prefix + '/logout' && req.method === 'POST') {
        sessions.delete(token)
        reply(res, 200, { ok: true }, { 'Set-Cookie': cookie('', 0, req) })
      } else if (path === prefix + '/config' && req.method === 'GET') {
        const timing = createTiming()
        const result = await timing.measure('config', () => getConfig(req))
        reply(res, 200, result, { 'Server-Timing': timing.header() })
      } else if (path === prefix + '/devices' && req.method === 'GET') {
        const timing = createTiming()
        const devices = await timing.measure('catalog-devices', () => getDevices(req))
        reply(res, 200, { devices }, { 'Server-Timing': timing.header() })
      } else if (path === prefix + '/targets' && req.method === 'GET') {
        const device = new URL(req.url, 'http://localhost').searchParams.get('device')
        const timing = createTiming()
        const targets = await timing.measure('catalog-targets', () => getTargets(req, device))
        reply(res, 200, { targets }, { 'Server-Timing': timing.header() })
      } else if (path === prefix + '/apply' && req.method === 'POST') {
        const timing = createTiming()
        try {
          const body = await timing.measure('body', () => readJsonBody(req, 524288))
          const result = await timing.measure('apply', () => apply(req, body, timing))
          reply(res, 200, result, { 'Server-Timing': timing.header() })
        } catch (error) {
          res.setHeader('Server-Timing', timing.header())
          throw error
        }
      } else {
        reply(res, 404, { error: 'Not found' })
      }
      return true
    } catch (error) {
      reply(res, error.status || 400, { error: error.message })
      return true
    }
  }

  return {
    handler,
    sessionActive: token => !closed && (sessions.get(token)?.expiry || 0) > Date.now(),
    sessionSnapshot () {
      return new Map([...sessions].filter(([, session]) => session.expiry > Date.now())
        .map(([token, session]) => [token, { ...session }]))
    },
    close () { closed = true; sessions.clear(); attempts.clear() }
  }
}

module.exports = { createPanelEditor }
